from math import gcd
from typing import List

class Solution:
    def maxScore(self, nums: List[int], maxVal: int) -> int:
        n = len(nums)
        M = max(maxVal, max(nums))
        present = set(nums)
        ans = 0
        for v in range(1, M + 1):
            c = sum(1 for x in nums if gcd(x, v) == 1)
            if v == 1:
                f = n - c if 1 in present else 1
            elif v in present:
                f = n - c - 1
            elif c < n:
                f = n - c
            else:
                f = 1
            ans = max(ans, v - f)
        return ans

