import java.util.*;

class Solution {
    public int maxScore(int[] nums, int maxVal) {
        int n = nums.length;
        int M = maxVal;
        for (int x : nums) M = Math.max(M, x);
        boolean[] present = new boolean[M + 1];
        for (int x : nums) present[x] = true;
        long ans = 0;
        for (int v = 1; v <= M; v++) {
            int c = 0;
            for (int x : nums) if (gcd(x, v) == 1) c++;
            long f;
            if (v == 1) f = present[1] ? n - c : 1;
            else if (present[v]) f = n - c - 1;
            else if (c < n) f = n - c;
            else f = 1;
            ans = Math.max(ans, v - f);
        }
        return (int) ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) { int t = a % b; a = b; b = t; }
        return a;
    }
}

