from typing import List

class Solution:
    def maxScore(self, nums: List[int], maxVal: int) -> int:
        n = len(nums)
        M = max(maxVal, max(nums))
        cnt = [0] * (M + 1)
        for x in nums:
            cnt[x] += 1
        mult = [0] * (M + 1)
        for d in range(1, M + 1):
            mult[d] = sum(cnt[m] for m in range(d, M + 1, d))
        spf = list(range(M + 1))
        i = 2
        while i * i <= M:
            if spf[i] == i:
                for j in range(i * i, M + 1, i):
                    if spf[j] == j:
                        spf[j] = i
            i += 1
        ans = 0
        for v in range(1, M + 1):
            t, primes = v, []
            while t > 1:
                p = spf[t]
                primes.append(p)
                while t % p == 0:
                    t //= p
            c = 0
            k = len(primes)
            for mask in range(1 << k):
                d, bits, mm, idx = 1, 0, mask, 0
                while mm:
                    if mm & 1:
                        d *= primes[idx]
                        bits += 1
                    mm >>= 1
                    idx += 1
                c += mult[d] if bits % 2 == 0 else -mult[d]
            if v == 1:
                f = n - c if cnt[1] > 0 else 1
            elif cnt[v] > 0:
                f = n - c - 1
            elif c < n:
                f = n - c
            else:
                f = 1
            ans = max(ans, v - f)
        return ans

